const _cache = new Map();

/** 构造一个图标的 mask data URI（带缓存）。 */
export function maskUrl(name) {
  if (_cache.has(name)) return _cache.get(name);
  const ic = ICONS[name];
  if (!ic) {
    console.warn('[icons] 未收录的图标:', name);
    _cache.set(name, 'none');
    return 'none';
  }
  const svg =
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${ic.vb}" fill="none" ` +
    `stroke="#000" stroke-width="${ic.sw}" stroke-linecap="round" stroke-linejoin="round">` +
    `${ic.d}</svg>`;
  const url = `url("data:image/svg+xml,${encodeURIComponent(svg)}")`;
  _cache.set(name, url);
  return url;
}

/** 生成图标元素的 HTML 串。size 为可选的字号类，如 'lg'。 */
export function iconHtml(name, size) {
  const u = maskUrl(name);
  const cls = 'icon' + (size ? ' icon--' + size : '');
  return `<span class="${cls}" style="-webkit-mask-image:${u};mask-image:${u}" aria-hidden="true"></span>`;
}

/** 把已存在的元素就地渲染为指定图标（用于动态更新）。 */
export function renderIcon(el, name) {
  const u = maskUrl(name);
  el.style.webkitMaskImage = u;
  el.style.maskImage = u;
  el.classList.add('icon');
}

export const ICON_NAMES = Object.keys(ICONS);
